#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=10

# Entra-App mit Zertifikat, Sites "Medienablage" + "Medienablage-Test", Bibliothek
# "Videos" (Versionslimit 5, Stufe "Bearbeiten ohne Löschen"), Netlify-Variablen.
# Voraussetzung: Schritt 1 ohne Blocker, Migration 20261201_medienablage.sql angewendet
# (Vault-RPC), Node 20+.
# Aufruf: bash scripts/medienablage/2-m365-einrichten.sh

SECRETS_DIR=".secrets"
KEY_FILE="$SECRETS_DIR/medienablage-app.key"
CRT_FILE="$SECRETS_DIR/medienablage-app.crt"
NETLIFY_IMPORT="$SECRETS_DIR/netlify-produktion.env"
SP_TENANT_HOST="$(_existing SP_TENANT_HOST || true)"
SP_TENANT_HOST="${SP_TENANT_HOST:-netorg12915005.sharepoint.com}"
SP_ADMIN_HOST="${SP_TENANT_HOST%.sharepoint.com}-admin.sharepoint.com"

banner "Medienablage · Schritt 2: Microsoft 365 einrichten"

stage "Zertifikat erzeugen (lokal)"
say "SharePoint-REST nimmt app-only nur mit Zertifikat an, nicht mit Client Secret."
mkdir -p "$SECRETS_DIR"; chmod 700 "$SECRETS_DIR"
if [[ -f "$KEY_FILE" && -f "$CRT_FILE" ]]; then
  note "Zertifikat existiert schon: $CRT_FILE"
  openssl x509 -in "$CRT_FILE" -noout -enddate | sed 's/^/  /'
elif confirm "Neues Zertifikat (RSA 2048, 2 Jahre) in $SECRETS_DIR anlegen?"; then
  openssl req -x509 -newkey rsa:2048 -sha256 -days 730 -nodes \
    -subj "/CN=CRM Medienablage" -keyout "$KEY_FILE" -out "$CRT_FILE" >/dev/null 2>&1
  chmod 600 "$KEY_FILE"
  printf '  %s✓%s %s und %s\n' "$GREEN" "$RESET" "$KEY_FILE" "$CRT_FILE"
fi
pause

stage "App registrieren"
open_url "https://entra.microsoft.com/#view/Microsoft_AAD_RegisteredApps/CreateApplicationBlade/quickStartType~/null/isMSAApp~/false"
step "Name: CRM Medienablage"
step "Unterstützte Kontotypen: 'Nur Konten in diesem Organisationsverzeichnis'"
step "Umleitungs-URI leer lassen → Registrieren"
step "Auf der Übersicht 'Anwendungs-ID (Client)' kopieren."
ask MS_CLIENT_ID "Anwendungs-ID (Client-ID):"
write_env MS_CLIENT_ID "$MS_CLIENT_ID"
pause

stage "Zertifikat hochladen"
open_url "https://entra.microsoft.com/#view/Microsoft_AAD_RegisteredApps/ApplicationMenuBlade/~/Credentials/appId/${MS_CLIENT_ID}"
step "Zertifikate und Geheimnisse → Reiter 'Zertifikate' → 'Zertifikat hochladen'"
step "Datei: $(pwd)/$CRT_FILE  ·  Beschreibung: CRM Medienablage"
note "Kein Client Secret anlegen."
pause "Hochgeladen? Enter"

stage "API-Berechtigungen + Administratorzustimmung"
open_url "https://entra.microsoft.com/#view/Microsoft_AAD_RegisteredApps/ApplicationMenuBlade/~/CallAnAPI/appId/${MS_CLIENT_ID}"
step "Berechtigung hinzufügen → Microsoft Graph → Anwendungsberechtigungen → Sites.Selected"
step "Berechtigung hinzufügen → SharePoint → Anwendungsberechtigungen → Sites.Selected"
step "Die vorhandene delegierte Berechtigung User.Read darf bleiben."
step "'Administratorzustimmung für ... erteilen' klicken. Beide Zeilen müssen grün 'Gewährt' zeigen."
note "Sites.Selected heißt: die App sieht nur Sites, die wir ihr in Stufe 6 ausdrücklich geben."
pause "Zustimmung erteilt? Enter"

stage "Sites anlegen"
open_url "https://${SP_ADMIN_HOST}/_layouts/15/online/AdminHome.aspx#/siteManagement"
step "Erstellen → 'Kommunikationswebsite' (keine Microsoft 365-Gruppe, sonst sehen Gruppenmitglieder alles)"
step "Name: Medienablage  ·  Adresse: /sites/Medienablage  ·  Sprache: Deutsch"
step "Noch einmal: Name Medienablage-Test  ·  Adresse: /sites/Medienablage-Test"
ask SP_SITE_URL "URL der Site Medienablage [Enter = https://${SP_TENANT_HOST}/sites/Medienablage]:"
SP_SITE_URL="${SP_SITE_URL:-https://${SP_TENANT_HOST}/sites/Medienablage}"
ask SP_TEST_SITE_URL "URL der Test-Site [Enter = https://${SP_TENANT_HOST}/sites/Medienablage-Test]:"
SP_TEST_SITE_URL="${SP_TEST_SITE_URL:-https://${SP_TENANT_HOST}/sites/Medienablage-Test}"
write_env SP_SITE_URL "$SP_SITE_URL"
write_env SP_TEST_SITE_URL "$SP_TEST_SITE_URL"
pause

stage "Der App Zugriff auf genau diese zwei Sites geben"
say "Das geht nur als Admin über Graph Explorer (einmalig, delegiert)."
open_url "https://developer.microsoft.com/de-de/graph/graph-explorer"
step "Als Admin anmelden. 'Berechtigungen ändern' → Sites.FullControl.All zustimmen."
for url in "$SP_SITE_URL" "$SP_TEST_SITE_URL"; do
  sitepath="${url#https://${SP_TENANT_HOST}}"
  say ""
  say "${BOLD}Site ${sitepath}${RESET}"
  step "GET  https://graph.microsoft.com/v1.0/sites/${SP_TENANT_HOST}:${sitepath}?\$select=id  → 'id' merken"
  step "POST https://graph.microsoft.com/v1.0/sites/{id}/permissions  mit Body:"
  printf '      {"roles":["write"],"grantedToIdentities":[{"application":{"id":"%s","displayName":"CRM Medienablage"}}]}\n' "$MS_CLIENT_ID"
  step "PATCH https://graph.microsoft.com/v1.0/sites/{id}/permissions/{permission-id aus der Antwort}  mit Body:"
  printf '      {"roles":["fullcontrol"]}\n'
done
note "fullcontrol braucht die App für eigene Berechtigungsstufen und Ordnerrechte (SharePoint-REST)."
pause "Beide Sites freigegeben? Enter"

stage "Zertifikat in den Supabase Vault"
say "Netlify-Functions dürfen nur 4 KB Env-Variablen haben, Schlüssel und Zertifikat liegen deshalb im Vault."
note "Braucht SUPABASE_URL und SUPABASE_SERVICE_ROLE_KEY in .env und die Migration 20261201_medienablage.sql."
if confirm "Schlüssel und Zertifikat jetzt in den Vault schreiben?"; then
  node scripts/medienablage/vault-setzen.mjs --key "$KEY_FILE" --cert "$CRT_FILE" \
    || warn "Vault-Schreiben fehlgeschlagen: Ausgabe oben prüfen, Stufe erneut laufen lassen."
else
  SKIPPED+=("node scripts/medienablage/vault-setzen.mjs --key $KEY_FILE --cert $CRT_FILE")
fi
pause

stage "Sites einrichten (Bibliothek, Versionen, Berechtigungsstufe)"
say "Das Skript legt in jeder Site die Bibliothek 'Videos' an (Versionslimit 5),"
say "die Stufe 'Bearbeiten ohne Löschen' und gibt Site-ID und Drive-ID aus."
if confirm "Test-Site jetzt einrichten?"; then
  node scripts/medienablage/site-einrichten.mjs --site "$SP_TEST_SITE_URL" --env-prefix SP_TEST_ \
    | tee "$SECRETS_DIR/site-test.out" || warn "Fehlgeschlagen, Ausgabe prüfen."
  SP_TEST_SITE_ID=$(grep -E '^SP_TEST_SITE_ID=' "$SECRETS_DIR/site-test.out" | cut -d= -f2- || true)
  SP_TEST_DRIVE_ID=$(grep -E '^SP_TEST_DRIVE_ID=' "$SECRETS_DIR/site-test.out" | cut -d= -f2- || true)
  [[ -n "$SP_TEST_SITE_ID" ]] && write_env SP_TEST_SITE_ID "$SP_TEST_SITE_ID"
  [[ -n "$SP_TEST_DRIVE_ID" ]] && write_env SP_TEST_DRIVE_ID "$SP_TEST_DRIVE_ID"
fi
if confirm "Echte Site 'Medienablage' jetzt einrichten?"; then
  node scripts/medienablage/site-einrichten.mjs --site "$SP_SITE_URL" --env-prefix SP_ \
    | tee "$SECRETS_DIR/site-prod.out" || warn "Fehlgeschlagen, Ausgabe prüfen."
  SP_SITE_ID=$(grep -E '^SP_SITE_ID=' "$SECRETS_DIR/site-prod.out" | cut -d= -f2- || true)
  SP_DRIVE_ID=$(grep -E '^SP_DRIVE_ID=' "$SECRETS_DIR/site-prod.out" | cut -d= -f2- || true)
  [[ -n "$SP_SITE_ID" ]] && write_env SP_SITE_ID "$SP_SITE_ID"
  [[ -n "$SP_DRIVE_ID" ]] && write_env SP_DRIVE_ID "$SP_DRIVE_ID"
fi
pause

stage "Netlify-Variablen (Produktion)"
SP_WEBHOOK_CLIENT_STATE="$(_existing SP_WEBHOOK_CLIENT_STATE || true)"
[[ -z "$SP_WEBHOOK_CLIENT_STATE" ]] && SP_WEBHOOK_CLIENT_STATE="$(openssl rand -hex 32)"
write_env SP_WEBHOOK_CLIENT_STATE "$SP_WEBHOOK_CLIENT_STATE"
ABLAGE_SECRET="$(_existing ABLAGE_SECRET || true)"
[[ -z "$ABLAGE_SECRET" ]] && ABLAGE_SECRET="$(openssl rand -hex 32)"
write_env ABLAGE_SECRET "$ABLAGE_SECRET"
umask 077
{
  printf 'MS_TENANT_ID=%s\n' "$(_existing MS_TENANT_ID || true)"
  printf 'MS_CLIENT_ID=%s\n' "$MS_CLIENT_ID"
  printf 'SP_SITE_URL=%s\n' "$SP_SITE_URL"
  printf 'SP_SITE_ID=%s\n' "$(_existing SP_SITE_ID || true)"
  printf 'SP_DRIVE_ID=%s\n' "$(_existing SP_DRIVE_ID || true)"
  printf 'SP_WEBHOOK_CLIENT_STATE=%s\n' "$SP_WEBHOOK_CLIENT_STATE"
  printf 'ABLAGE_SECRET=%s\n' "$ABLAGE_SECRET"
} > "$NETLIFY_IMPORT"
say "Datei für den Import: $(pwd)/$NETLIFY_IMPORT"
open_url "https://app.netlify.com/"
step "Produktions-Site → Site configuration → Environment variables → Add a variable → 'Import from a .env file'"
step "Inhalt der Datei einfügen, Scope: Functions, Kontexte: alle."
warn "ABLAGE_ZIEL NICHT setzen. Ohne Wert gilt die Weiche pro Unternehmen (Standard dropbox)."
note "Notschalter im Ernstfall: Admin → Medienablage → 'Alle zurück zu Dropbox' (sofort),"
note "oder ABLAGE_ZIEL=dropbox setzen und neu deployen (Env wirkt erst nach Deploy)."
pause "Importiert? Enter"

finish
note "Weiter mit: bash scripts/medienablage/3-staging-einrichten.sh"
note "Danach den Prototyp: node scripts/medienablage-spike.mjs --env .env.staging"
